(998, 1, 'CONSTELLATION', 'LONE STAR SS79', 'Aeroporto de Cabo Frio', '{"grupo":"CONSTELLATION","unidade":"LONE STAR SS79","data":"2026-08-26","local":"Aeroporto de Cabo Frio","modal":"Helicóptero","preposto":"Ítalo Gabriel","observacao_nome_arquivo":"","horarios":{"saida_hotel":[{"label1":"Previsto","h1":"07","m1":"00","label2":"Real","h2":"07","m2":"07"}],"embarque_previsto":"09:30","embarque_real":"12:16","atendimento_inicio":"07:07","atendimento_fim":"14:26"},"info_troca":"<div><span style=\"font-size: 1rem; -webkit-tap-highlight-color: transparent;\">Em<\/span><span style=\"font-size: 1rem; -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"> razão do teto baixo no Aeroporto de Cabo Frio, as operações aéreas foram temporariamente suspensas.&nbsp;<\/span><\/div><div><span style=\"font-size: 1rem; -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><br><\/span><\/div><div><span style=\"font-size: 1rem; -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Como medida preventiva, os colaboradores foram liberados até às 11h45min.<\/span><br><\/div><div><br><\/div><div>Após a reavaliação meteorológica da OMNI, a operação foi retomada e o voo ocorreu sem intercorrências.<\/div><b><div><b><br><\/b><\/div>Embarque material:<\/b><div>CARGO MANIFEST - TR - 21253.<\/div>","pax_embarcando":"*CONSTELLATION*\n1.JADIRLAN SCHUBERT DOS SANTOS\n2.JEFFERSON PESSANHA DOS SANTOS\n3.LAURO MONTEIRO FERNANDES\n4.LUCAS DE AZEVEDO MACIEL\n5.LUCAS ARAUJO DA SILVA\n6.MARLON BARRETO SANTOS","pax_desembarcando":"*CONSTELLATION*\n1.ANTONIO FLORENCIO DE OLIVEIRA NETO\n2.DOUGLAS DOS SANTOS VIEIRA\n3.JORGE LUIZ LAMOGLIA\n4.LEONARDO SILVA DOS REIS \n5.MAURICIO DE CASTRO GALVAO MOTTA\n6.RODRIGO FRANCA DO AMARAL COSTA\n\n*BRAVA ENERGIA*\n7.ALVARO GUILHERME ALTENKIRCH BORBA JUNIOR\n8.FRANCISCO ROSEMBERG DE GOIS ALENCAR\n9.PAULO ROBERTO CARDOSO NUNES\n\n*SLB*\n10.EMANUEL FAUSTO CHAGAS\n\n*SUBSEA 7*\n11.ALCIDES COSTA JUNIOR","fotos